const size_t jy_asset_count=sizeof jy_assets/sizeof jy_assets[0];
const jy_asset_entry *jy_asset_lookup(const char *path){size_t lo=0,hi=jy_asset_count;while(lo<hi){size_t mid=lo+(hi-lo)/2;int c=strcmp(path,jy_assets[mid].path);if(!c)return &jy_assets[mid];if(c<0)hi=mid;else lo=mid+1;}return NULL;}
int jy_asset_stat(void *ignored,const char *path,jy_fs_info *out){(void)ignored;if(!path||!out)return EINVAL;const jy_asset_entry *entry=jy_asset_lookup(path);if(entry){out->size=entry->bytes;out->kind=JY_FS_FILE;return 0;}size_t n=strlen(path);for(size_t i=0;i<jy_asset_count;++i){if(!n||(!strncmp(path,jy_assets[i].path,n)&&jy_assets[i].path[n]=='/')){out->size=0;out->kind=JY_FS_DIRECTORY;return 0;}}return ENOENT;}
